40. //==================================================================================================
41. // Constants
42. //==================================================================================================
43. 
44. // Use relaxed ordering for all atomic operations to mitigate synchronization overhead. It is safe
45. // to use this ordering semantics because Nanvix is a single-core system, and the kernel runs with
46. // interrupts disabled.
47. const ORDER: Ordering = Ordering::Relaxed;
48. 
49. //==================================================================================================
50. // Global Variables
51. //==================================================================================================
52. 
53. /// Physical memory manager storage.
54. static mut PHYS_MEMORY_MANAGER: MaybeUninit<PhysMemoryManager> = MaybeUninit::uninit();
55. 
56. /// Whether the physical memory manager has been initialized.
57. static PHYS_MEMORY_MANAGER_INIT: AtomicBool = AtomicBool::new(false);
58. 
59. //==================================================================================================
60. // Structures
61. //==================================================================================================
62. 
63. ///
64. /// # Description
65. ///
66. /// Physical memory manager.
67. ///
68. #[verus_verify]
69. pub struct PhysMemoryManager {
70.     upool: Upool,
71. }
72. 
73. //==================================================================================================
74. // Implementations
75. //==================================================================================================
76. 
77. #[verus_verify]
78. impl PhysMemoryManager {
79.     ///
80.     /// # Description
81.     ///
82.     /// Initializes the physical memory manager singleton.
83.     ///
84.     /// # Parameters
85.     ///
86.     /// - `upool`: User page pool.
87.     ///
88.     /// # Errors
89.     ///
90.     /// Returns `InvalidArgument` if the singleton has already been initialized.
91.     ///
92.     // TCB: bringing up the manager singleton writes a `MaybeUninit` static behind an
93.     // `AtomicBool` flag — raw-memory/atomics operations outside Verus's model. On success the
94.     // manager layer becomes ready (`phys_view().manager_ready`); the frame partition is
95.     // untouched. Listed in `verus-ai-logs/tcb-allowed.md`.
96.     #[verus_verify(external_body)]
97.     #[verus_spec(result =>
98.         ensures
99.             match result {
100.                 Ok(_) => crate::mm::phys::phys_view().manager_ready,
101.                 Err(_) => crate::mm::phys::phys_view().manager_ready,
102.             },
103.     )]
104.     pub(super) fn init(upool: Upool) -> Result<(), Error> {
105.         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
106.             return Err(Error::new(
107.                 ErrorCode::InvalidArgument,
108.                 "physical memory manager already initialized",
109.             ));
110.         }
111. 
112.         // SAFETY: this happens during kernel initialization and no other threads are running.
113.         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
114.         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
115.         Ok(())
116.     }
117. }
118. 
119. impl PhysMemoryManager {
120.     ///
121.     /// # Description
122.     ///
123.     /// Gets a mutable reference to the physical memory manager.
124.     ///
125.     /// # Panics
126.     ///
127.     /// Panics if the physical memory manager is not initialized.
128.     ///
129.     /// # Safety
130.     ///
131.     /// This function is unsafe because it returns a mutable reference to a global variable.
132.     ///
133.     /// The caller must ensure:
134.     ///
135.     /// - No other `&mut PhysMemoryManager` reference obtained from this function is live at the
136.     ///   same time (i.e., `&mut` references must not overlap). In practice this is guaranteed
137.     ///   because the kernel is single-threaded and runs with interrupts disabled, so no
138.     ///   re-entrant or concurrent call can alias the reference.
139.     ///
140.     pub unsafe fn get_mut<'a>() -> &'a mut PhysMemoryManager {
141.         if unlikely(!PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
142.             panic!("physical memory manager is not initialized");
143.         }
144. 
145.         // SAFETY: the physical memory manager has been initialized, so the value is valid.
146.         PHYS_MEMORY_MANAGER.assume_init_mut()
147.     }
148. }
149. 
150. #[verus_verify]
151. impl PhysMemoryManager {
152.     ///
153.     /// # Description
154.     ///
155.     /// Allocates user frames into caller-provided storage.
156.     ///
157.     /// The returned frames are not guaranteed to be physically contiguous.
158.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
159.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
160.     ///
161.     /// # Parameters
162.     ///
163.     /// - `count`: Number of frames to allocate.
164.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
165.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
166.     ///
167.     /// # Return Values
168.     ///
169.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
170.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
171.     /// back to empty.
172.     ///
173.     #[verus_spec(result =>
174.         requires
175.             self.inv(),
176.             old(frames)@.len() == 0,
177.         ensures
178.             final(self).inv(),
179.             match result {
180.                 Ok(()) => {
181.                     &&& (count > 0 ==> old(self)@.user_alloc_ok(count as nat))
182.                     &&& final(frames)@.len() == count
183.                     &&& user_addr_set(final(frames)@).len() == count
184.                     &&& old(self)@.all_free(user_addr_set(final(frames)@))
185.                     &&& final(self)@ == old(self)@.book_all(user_addr_set(final(frames)@))
186.                 },
187.                 Err(_) => {
188.                     &&& final(self)@ == old(self)@
189.                     &&& final(frames)@.len() == 0
190.                 },
191.             },
192.     )]
193.     pub fn alloc_many_user_frames(
194.         &mut self,
195.         count: usize,
196.         frames: &mut Vec<UserFrame>,
197.     ) -> Result<(), Error> {
198.         proof_decl! {
199.             let ghost g_old = self@;
200.         }
201.         proof! {
202.             assert(g_old == old(self)@);
203.             assert(g_old.wf());
204.         }
205.         if !frames.is_empty() {
206.             let reason: &str = "frames vector is not empty";
207.             #[cfg(not(verus_keep_ghost))]
208.             error!("{reason}");
209.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
210.         }
211.         if frames.capacity() < count {
212.             let reason: &str = "frames vector has insufficient capacity";
213.             #[cfg(not(verus_keep_ghost))]
214.             error!("{reason}");
215.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
216.         }
217. 
218.         // A zero-sized allocation is trivially satisfied.
219.         if count == 0 {
220.             proof! {
221.                 lemma_user_addr_set_empty(frames@);
222.                 lemma_book_all_empty(g_old);
223.             }
224.             return Ok(());
225.         }
226. 
227.         Self::check_user_watermark(count)?;
228.         proof! {
229.             lemma_manager_attached(self);
230.             lemma_user_addr_set_empty(frames@);
231.             lemma_book_all_empty(g_old);
232.         }
233. 
234.         #[allow(unused_variables)]
235.         #[verus_spec(
236.             invariant
237.                 g_old == old(self)@,
238.                 g_old.wf(),
239.                 self@.wf(),
240.                 frames@.len() == i,
241.                 user_addr_set(frames@).finite(),
242.                 user_addr_set(frames@).len() == i,
243.                 g_old.all_free(user_addr_set(frames@)),
244.                 self@ == g_old.book_all(user_addr_set(frames@)),
245.         )]
246.         for i in 0..count {
247.             proof_decl! {
248.                 let ghost frames_pre = frames@;
249.                 let ghost set_pre = user_addr_set(frames@);
250.             }
251.             match self.upool.alloc() {
252.                 Ok(frame) => {
253.                     frames.push(frame);
254.                     proof! {
255.                         // `self.upool.alloc()` moved `frame@` (free in `g_old`, not yet booked)
256.                         // out of the partition; fold it into the accumulated address set.
257.                         lemma_user_addr_set_push(frames_pre, frame);
258.                         lemma_book_all_alloc_one(g_old, set_pre, frame@);
259.                     }
260.                 },
261.                 Err(error) => {
262.                     frames.clear();
263.                     proof! {
264.                         lemma_user_bulk_err_restored(self, g_old);
265.                     }
266.                     return Err(error);
267.                 },
268.             }
269.         }
270.         Ok(())
271.     }
272. 
273.     ///
274.     /// # Description
275.     ///
276.     /// Allocates a single user frame, applying the same kernel watermark check as
277.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
278.     /// hot paths such as copy-on-write fault resolution, where allocating an
279.     /// intermediate [`Vec`] would be wasteful.
280.     ///
281.     /// # Returns
282.     ///
283.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
284.     /// instead.
285.     ///
286.     #[verus_spec(result =>
287.         requires
288.             self.inv(),
289.         ensures
290.             final(self).inv(),
291.             match result {
292.                 Ok(uf) => {
293.                     &&& old(self)@.user_alloc_ok(1)
294.                     &&& old(self)@.free_frames.contains(uf@)
295.                     &&& final(self)@ == old(self)@.alloc_one(uf@)
296.                 },
297.                 Err(_) => {
298.                     &&& final(self)@ == old(self)@
299.                     &&& !old(self)@.user_alloc_ok(1)
300.                 },
301.             },
302.     )]
303.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
304.         proof! {
305.             lemma_manager_attached(self);
306.         }
307.         Self::check_user_watermark(1)?;
308.         self.upool.alloc()
309.     }
310. 
311.     ///
312.     /// # Description
313.     ///
314.     /// Rejects user allocations of `count` frames that would breach the kernel
315.     /// watermark, i.e. that would drop the number of free frames below
316.     /// [`config::kernel::KERNEL_WATERMARK`].
317.     ///
318.     /// # Parameters
319.     ///
320.     /// - `count`: Number of user frames the caller intends to allocate.
321.     ///
322.     /// # Returns
323.     ///
324.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
325.     ///
326.     #[verus_spec(result =>
327.         ensures
328.             match result {
329.                 Ok(()) => crate::mm::phys::phys_view().frames.free_count()
330.                     >= count as nat + spec_kernel_watermark(),
331.                 Err(_) => crate::mm::phys::phys_view().frames.free_count()
332.                     < count as nat + spec_kernel_watermark(),
333.             },
334.     )]
335.     fn check_user_watermark(count: usize) -> Result<(), Error> {
336.         // VERUS DEVIATION (Verus-required, semantics-preserving): bind the current free-frame
337.         // count *before* the watermark-threshold computation. `frame::free_count()` is a pure read
338.         // whose `usize` result pins `phys_view().frames.free_count() <= usize::MAX`; the
339.         // watermark-overflow error path needs that bound to conclude the free count is below the
340.         // (overflowing) `watermark + count` threshold. Same call, same result; on the rare
341.         // overflow path it is now evaluated unconditionally (one extra O(1) bitmap read).
342.         let free: usize = frame::free_count();
343.         let watermark_threshold: usize = kernel_watermark()
344.             .checked_add(count)
345.             .ok_or_else(|| {
346.                 let reason: &str = "watermark + count overflow";
347.                 #[cfg(not(verus_keep_ghost))]
348.                 error!("{reason}");
349.                 Error::new(ErrorCode::InvalidArgument, reason)
350.             })?;
351.         if free < watermark_threshold {
352.             let reason: &str = "would breach kernel watermark";
353.             #[cfg(not(verus_keep_ghost))]
354.             error!("{reason}");
355.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
356.         }
357.         Ok(())
358.     }
359. 
360.     ///
361.     /// # Description
362.     ///
363.     /// Allocates a kernel frame.
364.     ///
365.     /// Kernel allocations bypass the watermark — no artificial ceiling.
366.     ///
367.     /// # Return Values
368.     ///
369.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
370.     ///
371.     #[verus_spec(result =>
372.         requires
373.             self.inv(),
374.         ensures
375.             final(self).inv(),
376.             match result {
377.                 Ok(kf) => {
378.                     &&& old(self)@.free_frames.contains(kf@)
379.                     &&& final(self)@ == old(self)@.alloc_one(kf@)
380.                 },
381.                 Err(_) => final(self)@ == old(self)@,
382.             },
383.     )]
384.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
385.         proof_decl! {
386.             let ghost g_old = self@;
387.         }
388.         let frame_addr: FrameAddress = frame::alloc()?;
389.         let result: Result<KernelFrame, Error> = KernelFrame::new(frame_addr).inspect_err(|e| {
390.             #[cfg(not(verus_keep_ghost))]
391.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
392.             if let Err(free_err) = frame::free(frame_addr) {
393.                 #[cfg(not(verus_keep_ghost))]
394.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
395.             }
396.         });
397.         proof! {
398.             if result is Ok {
399.                 lemma_kernel_alloc_one(g_old, self@, result->Ok_0@);
400.             }
401.         }
402.         result
403.     }
404. 
405.     ///
406.     /// # Description
407.     ///
408.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
409.     ///
410.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
411.     /// mapping and the hardware stack pointer traverses the region linearly.
412.     /// Kernel allocations bypass the watermark — no artificial ceiling.
413.     ///
414.     /// # Parameters
415.     ///
416.     /// - `count`: Number of frames to allocate.
417.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
418.     ///   those frames' addresses.
419.     ///
420.     /// # Return Values
421.     ///
422.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
423.     /// contiguous entries. Upon failure, an error is returned instead.
424.     ///
425.     #[verus_spec(result =>
426.         requires
427.             self.inv(),
428.             old(frames)@.len() == 0,
429.             count > 0,
430.         ensures
431.             final(self).inv(),
432.             match result {
433.                 Ok(()) => {
434.                     &&& final(frames)@.len() == count
435.                     &&& kernel_frames_contiguous(final(frames)@, count as nat)
436.                     &&& old(self)@.all_free(kernel_addr_set(final(frames)@))
437.                     &&& final(self)@ == old(self)@.book_all(kernel_addr_set(final(frames)@))
438.                 },
439.                 Err(_) => {
440.                     &&& final(self)@ == old(self)@
441.                     &&& final(frames)@.len() == 0
442.                 },
443.             },
444.     )]
445.     pub fn alloc_many_kernel_frames(
446.         &mut self,
447.         count: usize,
448.         frames: &mut Vec<KernelFrame>,
449.     ) -> Result<(), Error> {
450.         proof_decl! {
451.             let ghost g_old = self@;
452.         }
453.         proof! {
454.             assert(g_old == old(self)@);
455.             assert(g_old.wf());
456.         }
457.         // Check if caller-provided vector is not empty.
458.         if !frames.is_empty() {
459.             let reason: &str = "frames vector is not empty";
460.             #[cfg(not(verus_keep_ghost))]
461.             error!("{reason}");
462.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
463.         }
464.         if frames.capacity() < count {
465.             let reason: &str = "frames vector has insufficient capacity";
466.             #[cfg(not(verus_keep_ghost))]
467.             error!("{reason}");
468.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
469.         }
470. 
471.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
472.         let base_raw: usize = base_addr.into_raw_value();
473.         #[verus_spec(
474.             invariant
475.                 g_old == old(self)@,
476.                 g_old.wf(),
477.                 self@ == g_old,
478.                 base_raw as int == base_addr@,
479.                 base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
480.         )]
481.         for i in 0..count {
482.             proof! {
483.                 lemma_contig_no_overflow(base_raw, i, count);
484.             }
485.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
486.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
487.                 Ok(kf) => frames.push(kf),
488.                 Err(e) => {
489.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
490.                     frames.clear();
491.                     // Free remaining un-wrapped frames from the contiguous allocation.
492.                     #[verus_spec(
493.                         invariant
494.                             g_old == old(self)@,
495.                             g_old.wf(),
496.                             self@ == g_old,
497.                             base_raw as int == base_addr@,
498.                             base_raw as int + (count as int) * spec_page_size()
499.                                 <= usize::MAX as int,
500.                     )]
501.                     for j in i..count {
502.                         proof! {
503.                             lemma_contig_no_overflow(base_raw, j, count);
504.                         }
505.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
506.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
507.                             if let Err(e) = frame::free(fa) {
508.                                 #[cfg(not(verus_keep_ghost))]
509.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
510.                             }
511.                         }
512.                     }
513.                     return Err(e);
514.                 },
515.             }
516.         }
517.         proof! {
518.             lemma_kernel_alloc_contiguous(g_old, self@, frames@, count as nat);
519.         }
520.         Ok(())
521.     }
522. }
523. 
524. //==================================================================================================
525. // Build-time constant accessors
526. //==================================================================================================
527. 
528. // External-bottom trust boundary: `config::kernel::KERNEL_WATERMARK` is generated by the `config`
529. // crate's `build.rs` (from `kernel_config.toml`) and lives in a non-Verus dependency crate, so
530. // Verus cannot resolve its value. This accessor ties the runtime constant to the abstract
531. // `spec_kernel_watermark()`. Listed in `verus-ai-logs/tcb-allowed.md`.
532. #[verus_verify(external_body)]
533. #[verus_spec(ret =>
534.     ensures
535.         ret as nat == spec_kernel_watermark(),
536. )]
537. fn kernel_watermark() -> usize {
538.     config::kernel::KERNEL_WATERMARK
539. }
540.

